/* =========================================================
   Skill 5 · 战略与治理分析报告 · 样式覆盖
   ---------------------------------------------------------
   本文件 **仅追加** skill5 专属组件，不覆盖 skill3 style_guide.css
   的任何变量或基础类。注入顺序：
     1. style_guide.css（基础）
     2. style_overrides.css（本文件，追加）
   ========================================================= */

/* ========== 1. 领导时间线 · .leader-timeline ========== */
.leader-timeline {
    width: 100%;
    margin: 5mm 0;
    overflow-x: auto;
    page-break-inside: avoid;
    break-inside: avoid;
}

.leader-timeline table {
    width: 100%;
    border-collapse: collapse;
    font-size: 8.5pt;
    table-layout: fixed;
}

.leader-timeline th {
    background: var(--accent);
    color: #fff;
    padding: 4pt 6pt;
    text-align: center;
    font-weight: 600;
    font-size: 8pt;
    letter-spacing: 0.5px;
    white-space: nowrap;
}

.leader-timeline th.bank-col {
    width: 12%;
    text-align: left;
}

.leader-timeline td {
    padding: 2pt 1pt;
    border: 0.5pt solid var(--border);
    vertical-align: middle;
    text-align: center;
    height: 22pt;
    position: relative;
}

.leader-timeline td.bank-label {
    font-weight: 600;
    color: var(--primary-dark);
    text-align: left;
    padding-left: 6pt;
    background: var(--bg-light);
}

/* 任期色块 */
.leader-timeline .tenure-bar {
    display: inline-block;
    height: 16pt;
    border-radius: 2pt;
    color: #fff;
    font-size: 7pt;
    font-weight: 600;
    line-height: 16pt;
    padding: 0 4pt;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
}

/* 按领导者背景类型着色 */
.tenure-bar.internal   { background: var(--primary); }
.tenure-bar.system     { background: var(--accent); }
.tenure-bar.regulator  { background: var(--efficiency-blue); }
.tenure-bar.external   { background: var(--growth-green); }

.leader-timeline .timeline-legend {
    display: flex;
    gap: 12pt;
    margin-top: 3mm;
    font-size: 8.5pt;
    color: var(--text-secondary);
}

.leader-timeline .legend-item {
    display: flex;
    align-items: center;
    gap: 4pt;
}

.leader-timeline .legend-swatch {
    display: inline-block;
    width: 12pt;
    height: 8pt;
    border-radius: 1pt;
}

.legend-swatch.internal   { background: var(--primary); }
.legend-swatch.system     { background: var(--accent); }
.legend-swatch.regulator  { background: var(--efficiency-blue); }
.legend-swatch.external   { background: var(--growth-green); }

/* ========== 2. 组织变革热力图 · .org-heatmap ========== */
.org-heatmap {
    width: 100%;
    margin: 5mm 0;
    page-break-inside: avoid;
    break-inside: avoid;
}

.org-heatmap table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9pt;
}

.org-heatmap th {
    background: var(--accent);
    color: #fff;
    padding: 4pt 6pt;
    text-align: center;
    font-weight: 600;
    font-size: 8.5pt;
}

.org-heatmap th.bank-col {
    width: 14%;
    text-align: left;
}

.org-heatmap th.line-col {
    width: 8%;
}

.org-heatmap td {
    padding: 3pt 4pt;
    border: 0.5pt solid var(--border);
    text-align: center;
    font-variant-numeric: tabular-nums;
    font-weight: 600;
    font-size: 9pt;
}

.org-heatmap td.bank-label {
    text-align: left;
    font-weight: 600;
    color: var(--primary-dark);
    background: var(--bg-light);
    padding-left: 6pt;
}

.org-heatmap td.line-label {
    text-align: left;
    font-size: 8.5pt;
    color: var(--text-secondary);
    background: var(--bg-light);
}

/* 热力深浅：变动次数 0~3+ */
.org-heatmap .heat-0 { background: var(--bg-white); color: var(--text-secondary); }
.org-heatmap .heat-1 { background: var(--primary-light); color: var(--primary-dark); }
.org-heatmap .heat-2 { background: #E8A0A8; color: #fff; }
.org-heatmap .heat-3 { background: var(--primary); color: #fff; }

/* ========== 3. 战略延续性三色标签 · .continuity-tag ========== */
.continuity-tag {
    display: inline-block;
    padding: 2pt 10pt;
    border-radius: 3pt;
    font-size: 9pt;
    font-weight: 600;
    color: #fff;
    letter-spacing: 0.5px;
    vertical-align: middle;
}

.continuity-tag.evolution   { background: var(--growth-green); }  /* 进化式继承 */
.continuity-tag.incremental { background: var(--accent); }        /* 渐进式调整 */
.continuity-tag.rupture     { background: var(--risk-red); }      /* 换届式创新 */

/* ========== 4. 反事实置信区间图 · .counterfactual-range ========== */
.counterfactual-range {
    margin: 5mm 0;
    padding: 4mm;
    background: var(--bg-light);
    border: 0.5pt solid var(--border);
    border-radius: 2pt;
    page-break-inside: avoid;
    break-inside: avoid;
}

.counterfactual-range .cf-title {
    font-size: 10pt;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 4mm;
}

.counterfactual-range .cf-row {
    display: flex;
    align-items: center;
    margin: 3mm 0;
    gap: 6pt;
}

.counterfactual-range .cf-label {
    width: 30%;
    font-size: 9pt;
    color: var(--text-secondary);
    text-align: right;
    padding-right: 6pt;
    flex-shrink: 0;
}

.counterfactual-range .cf-bar-container {
    flex: 1;
    height: 18pt;
    background: var(--bg-white);
    border: 0.5pt solid var(--border);
    border-radius: 2pt;
    position: relative;
    overflow: hidden;
}

.counterfactual-range .cf-bar {
    height: 100%;
    border-radius: 2pt;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 7.5pt;
    font-weight: 600;
    color: #fff;
    white-space: nowrap;
}

/* 置信度着色 */
.cf-bar.confidence-low    { background: var(--text-secondary); }
.cf-bar.confidence-medium { background: var(--accent); }
.cf-bar.confidence-high   { background: var(--primary); }

.counterfactual-range .cf-endpoints {
    display: flex;
    justify-content: space-between;
    font-size: 7.5pt;
    color: var(--text-secondary);
    margin-top: 1pt;
    padding: 0 2pt;
}

/* 反事实声明（每页底部） */
.cf-disclaimer {
    margin-top: 4mm;
    padding: 3mm 4mm;
    background: #FFF3E0;
    border-left: 3pt solid var(--accent);
    font-size: 8.5pt;
    color: var(--text-secondary);
    font-style: italic;
}

/* ========== 5. 战略摇摆点诊断卡 · .swing-card ========== */
.swing-card {
    margin: 6mm 0;
    padding: 7mm;
    background: var(--bg-white);
    border: 1pt solid var(--border);
    border-left: 5pt solid var(--risk-red);
    border-radius: 2pt;
    page-break-inside: avoid;
    break-inside: avoid;
}

.swing-card .swing-header {
    display: flex;
    align-items: baseline;
    gap: 8pt;
    margin-bottom: 4mm;
    flex-wrap: wrap;
}

.swing-card .swing-year {
    font-size: 18pt;
    font-weight: 700;
    color: var(--risk-red);
    font-variant-numeric: tabular-nums;
}

.swing-card .swing-badge {
    display: inline-block;
    padding: 2pt 10pt;
    background: var(--risk-red);
    color: #fff;
    font-size: 9pt;
    font-weight: 600;
    border-radius: 3pt;
    letter-spacing: 1px;
}

.swing-card .swing-title {
    font-size: 13pt;
    color: var(--text-primary);
    font-weight: 600;
    flex: 1 0 100%;
    margin-top: 2mm;
}

.swing-card .swing-section {
    margin-top: 4mm;
}

.swing-card .swing-section-label {
    font-size: 9.5pt;
    font-weight: 700;
    color: var(--risk-red);
    letter-spacing: 1px;
    margin-bottom: 2mm;
    display: inline-block;
    padding: 1pt 6pt;
    background: #FFEBEE;
    border-radius: 2pt;
}

.swing-card .swing-section p,
.swing-card .swing-section ul {
    margin: 2mm 0;
    line-height: 1.7;
}

.swing-card .swing-section ul {
    padding-left: 20px;
}

.swing-card .swing-section li {
    margin: 3pt 0;
}

.swing-card .swing-section li::marker {
    color: var(--risk-red);
}

/* ========== 6. 建议三栏布局 · .recommendation-col ========== */
.recommendation-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 5mm;
    margin: 5mm 0;
}

/* 三个栏目 */
.recommendation-col {
    page-break-inside: avoid;
    break-inside: avoid;
}

.recommendation-col .col-header {
    padding: 4mm;
    color: #fff;
    font-size: 11pt;
    font-weight: 700;
    text-align: center;
    letter-spacing: 1px;
    border-radius: 2pt 2pt 0 0;
    margin-bottom: 3mm;
}

.recommendation-col.strategy-insulation .col-header  { background: var(--growth-green); }
.recommendation-col.governance-resilience .col-header { background: var(--efficiency-blue); }
.recommendation-col.key-personnel .col-header         { background: var(--primary); }

/* 栏内单条建议复用 .insight-card */
.recommendation-col .insight-card {
    margin: 3mm 0;
    padding: 4mm;
    font-size: 9pt;
}

.recommendation-col.strategy-insulation .insight-card  { border-left-color: var(--growth-green); }
.recommendation-col.governance-resilience .insight-card { border-left-color: var(--efficiency-blue); }
.recommendation-col.key-personnel .insight-card         { border-left-color: var(--primary); }

/* 建议六要素紧凑排列 */
.rec-field {
    margin: 2mm 0;
    line-height: 1.6;
}

.rec-field-label {
    display: inline-block;
    font-weight: 700;
    font-size: 8pt;
    color: var(--text-secondary);
    letter-spacing: 0.5px;
    min-width: 50pt;
}

/* ========== 7. 基准行高亮（表格中） ========== */
.row-highlight {
    background: var(--primary-light) !important;
}

.row-highlight td {
    font-weight: 600;
    color: var(--primary-dark);
}

/* ========== 8. 分页与排版补充 ========== */
.leader-timeline,
.org-heatmap,
.counterfactual-range,
.swing-card,
.recommendation-col {
    page-break-inside: avoid;
    break-inside: avoid;
}

/* 三栏在窄页面降级为单列 */
@media (max-width: 180mm) {
    .recommendation-grid {
        grid-template-columns: 1fr;
    }
}

/* 打印时保持热力图颜色 */
@media print {
    .org-heatmap .heat-1,
    .org-heatmap .heat-2,
    .org-heatmap .heat-3 {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }

    .tenure-bar,
    .continuity-tag,
    .cf-bar,
    .swing-badge,
    .recommendation-col .col-header {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}

